278	/**
279	 * Parses CSV text into an array of records: arrays of strings, or objects keyed
280	 * by the first record when `options.header` is true.
281	 *
282	 * @param {string} text
283	 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
284	 * @returns {Array<string[]> | Array<Record<string, string>>}
285	 * @throws {TypeError} if `text` is not a string or an option is invalid.
286	 * @throws {CsvError} if the input is malformed.
287	 */
288	function parse(text, options = {}) {
289	  if (typeof text !== 'string') {
290	    throw new TypeError(`text must be a string, received ${describe(text)}`);
291	  }
292	  const tokenizer = new Tokenizer(options);
293	  tokenizer.feed(text);
294	  tokenizer.finish();
295	  return tokenizer.take();
296	}
297	
298	/**
299	 * Creates a streaming parser with the same options and results as `parse`.
300	 * `write(chunk)` returns the records whose terminating line break was in
301	 * `chunk`; `end()` returns the rest. Once `end()` has been called or either
302	 * method has thrown, both methods throw.
303	 *
304	 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
305	 * @returns {{write(chunk: string): Array, end(): Array}}
306	 */
307	function createParser(options = {}) {
308	  const tokenizer = new Tokenizer(options);
309	  let closedReason = null;
310	
311	  function run(method, step) {
312	    if (closedReason !== null) {
313	      throw new Error(`Cannot call ${method}(): the parser ${closedReason}`);
314	    }
315	    try {
316	      step();
317	    } catch (err) {
318	      closedReason = 'failed with an earlier error';
319	      throw err;
320	    }
321	    return tokenizer.take();
322	  }
323	
324	  return {
325	    write(chunk) {
326	      return run('write', () => {
327	        if (typeof chunk !== 'string') {
328	          throw new TypeError(`chunk must be a string, received ${describe(chunk)}`);
329	        }
330	        tokenizer.feed(chunk);
331	      });
332	    },
333	    end() {
334	      const records = run('end', () => tokenizer.finish());
335	      closedReason = 'has already ended';
336	      return records;
337	    },
338	  };
339	}
340	
341	function toText(value, rowIndex, fieldIndex) {
342	  switch (typeof value) {
343	    case 'string':
344	      return value;
345	    case 'number':
346	    case 'boolean':
347	      return String(value);
348	    case 'undefined':
349	      return '';
350	    default:
351	      if (value === null) return '';
352	      throw new TypeError(
353	        `Unsupported value of type ${describe(value)} in row ${rowIndex}, field ${fieldIndex}`,
354	      );
355	  }
356	}
357	
358	function quote(text) {
359	  return `"${text.replace(/"/g, '""')}"`;
360	}
361	
362	function formatField(text, delimiter) {
363	  if (
364	    /["\r\n]/.test(text) ||
365	    text.includes(delimiter) ||
366	    text.startsWith(' ') ||
367	    text.endsWith(' ')
368	  ) {
369	    return quote(text);
370	  }
371	  return text;
372	}
373	
374	function formatRecord(values, delimiter, rowIndex, isFirstLine) {
375	  const fields = new Array(values.length);
376	  for (let k = 0; k < values.length; k++) {
377	    fields[k] = formatField(toText(values[k], rowIndex, k), delimiter);
378	  }
379	  // An empty line would parse back as [''] or be skipped, so keep the field visible.
380	  if (fields.length === 1 && fields[0] === '') return '""';
381	  const line = fields.join(delimiter);
382	  if (isFirstLine && line.charCodeAt(0) === BOM) {
383	    // parse drops a leading U+FEFF as a byte order mark. Only an unquoted first
384	    // field can put one there (by starting with it, or by being empty before a
385	    // U+FEFF delimiter), and such a field has no `"` to escape.
386	    fields[0] = `"${fields[0]}"`;
387	    return fields.join(delimiter);
388	  }
389	  return line;
390	}
391	
392	function resolveHeader(header) {
393	  if (header === undefined || header === null || header === false) return null;
394	  if (!Array.isArray(header)) {
395	    throw new TypeError(`options.header must be an array of column names, received ${describe(header)}`);
396	  }
397	  for (let k = 0; k < header.length; k++) {
398	    if (typeof header[k] !== 'string') {
399	      throw new TypeError(`options.header[${k}] must be a string, received ${describe(header[k])}`);
400	    }
401	  }
402	  return header;
403	}
404	
405	/**
406	 * Serializes records to CSV text. Each record is an array of values, or, when
407	 * `options.header` is an array of column names, an object whose own properties
408	 * are written in header order after a header row.
409	 *
410	 * @param {Array<Array<unknown> | Record<string, unknown>>} rows
411	 * @param {{delimiter?: string, eol?: '\r\n' | '\n', header?: string[]}} [options]
412	 * @returns {string} The CSV text, ending with `eol`, or '' when nothing is written.
413	 * @throws {TypeError} for invalid rows, values or options.
414	 */
415	function stringify(rows, options = {}) {
416	  if (!Array.isArray(rows)) {
417	    throw new TypeError(`rows must be an array, received ${describe(rows)}`);
418	  }
419	  checkOptionsObject(options);
420	  const delimiter = resolveDelimiter(options.delimiter);
421	  const eol = options.eol === undefined ? DEFAULT_EOL : options.eol;
422	  if (!ALLOWED_EOLS.includes(eol)) {
423	    throw new TypeError(`options.eol must be '\\r\\n' or '\\n', received ${describeReceived(eol)}`);
424	  }
425	  const header = resolveHeader(options.header);
426	
427	  const lines = [];
428	  if (header !== null) lines.push(formatRecord(header, delimiter, 'header', true));
429	  for (let r = 0; r < rows.length; r++) {
430	    const row = rows[r];
431	    let values;
432	    if (Array.isArray(row)) {
433	      values = row;
434	    } else if (header !== null && typeof row === 'object' && row !== null) {
435	      values = header.map((name) => (Object.hasOwn(row, name) ? row[name] : undefined));
436	    } else {
437	      const expected = header === null ? 'an array' : 'an array or an object';
438	      throw new TypeError(`Row ${r} must be ${expected}, received ${describe(row)}`);
439	    }
440	    lines.push(formatRecord(values, delimiter, r, lines.length === 0));
441	  }
442	  if (lines.length === 0) return '';
443	  return lines.join(eol) + eol;
444	}
445	
446	module.exports = { parse, createParser, stringify, CsvError };
