'use strict';

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const BOM = 0xfeff;

const DEFAULT_DELIMITER = ',';
const DEFAULT_EOL = '\r\n';
const ALLOWED_EOLS = ['\r\n', '\n'];

// Tokenizer states.
const RECORD_START = 0;
const FIELD_START = 1; // right after a delimiter
const UNQUOTED = 2;
const QUOTED = 3;
const QUOTE_IN_QUOTED = 4; // saw `"` inside a quoted field: a close or the first half of `""`

/**
 * Thrown for malformed CSV input. `line` and `column` are 1-based; columns
 * count UTF-16 code units.
 */
class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function describe(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

// Shows a rejected option value. Only strings are serialized: JSON.stringify
// can throw for BigInts, cycles or a custom toJSON, which would replace the
// TypeError being built.
function describeReceived(value) {
  return typeof value === 'string' ? JSON.stringify(value) : describe(value);
}

function checkOptionsObject(options) {
  if (typeof options !== 'object' || options === null || Array.isArray(options)) {
    throw new TypeError(`options must be an object, received ${describe(options)}`);
  }
}

function resolveDelimiter(delimiter) {
  if (delimiter === undefined) return DEFAULT_DELIMITER;
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `options.delimiter must be a single character other than '"', CR or LF, received ${describeReceived(delimiter)}`,
    );
  }
  return delimiter;
}

function resolveBoolean(options, name) {
  const value = options[name];
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`options.${name} must be a boolean, received ${describe(value)}`);
  }
  return value;
}

/**
 * Incremental CSV state machine. `parse` feeds it the whole input at once and
 * `createParser` feeds it chunk by chunk, so both see identical records and
 * errors wherever the input is split. Each character is visited once.
 */
class Tokenizer {
  constructor(options) {
    checkOptionsObject(options);
    this.delimiter = resolveDelimiter(options.delimiter).charCodeAt(0);
    this.header = resolveBoolean(options, 'header');
    this.skipEmptyLines = resolveBoolean(options, 'skipEmptyLines');

    this.state = RECORD_START;
    this.started = false; // a leading BOM is only possible before the first character
    // Position of the next character.
    this.line = 1;
    this.column = 1;
    this.lastWasCR = false;

    this.fields = [];
    this.field = ''; // content of the current field from earlier chunks or before an escaped quote
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;

    this.columns = null; // header names, once the header record has been read
    this.headerNames = this.header ? new Set() : null;
    this.records = [];
  }

  feed(chunk) {
    const length = chunk.length;
    let i = 0;
    if (!this.started && length > 0) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    // Start of field content not yet copied into this.field (UNQUOTED and QUOTED only).
    let segmentStart = i;

    for (; i < length; i++) {
      const c = chunk.charCodeAt(i);
      const isBreak = c === CR || c === LF;

      switch (this.state) {
        case RECORD_START:
          if (c === LF && this.lastWasCR) break; // second half of a CRLF that ended a record
          if (isBreak) {
            if (!this.skipEmptyLines) {
              this.recordLine = this.line;
              this.fields.push('');
              this.endRecord();
            }
            break;
          }
          this.recordLine = this.line;
          segmentStart = this.startField(c, i);
          break;
        case FIELD_START:
          if (isBreak) {
            this.fieldLine = this.line;
            this.fieldColumn = this.column;
            this.endField('');
            this.endRecord();
            break;
          }
          segmentStart = this.startField(c, i);
          break;
        case UNQUOTED:
          if (c === this.delimiter || isBreak) {
            this.endField(this.field + chunk.slice(segmentStart, i));
            if (isBreak) this.endRecord();
          }
          break;
        case QUOTED:
          if (c === QUOTE) {
            this.field += chunk.slice(segmentStart, i);
            this.state = QUOTE_IN_QUOTED;
          }
          break;
        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            this.field += '"';
            segmentStart = i + 1;
            this.state = QUOTED;
          } else if (c === this.delimiter || isBreak) {
            this.endField(this.field);
            if (isBreak) this.endRecord();
          } else {
            throw new CsvError(
              `Unexpected character ${JSON.stringify(chunk[i])} after closing quote`,
              this.line,
              this.column,
            );
          }
          break;
      }

      if (c === CR) {
        this.line++;
        this.column = 1;
        this.lastWasCR = true;
      } else if (c === LF) {
        if (!this.lastWasCR) {
          this.line++;
          this.column = 1;
        }
        this.lastWasCR = false;
      } else {
        this.column++;
        this.lastWasCR = false;
      }
    }

    if (this.state === UNQUOTED || this.state === QUOTED) {
      this.field += chunk.slice(segmentStart, length);
    }
  }

  finish() {
    switch (this.state) {
      case RECORD_START:
        return;
      case FIELD_START:
        this.fieldLine = this.line;
        this.fieldColumn = this.column;
        this.endField('');
        break;
      case QUOTED:
        throw new CsvError('Unclosed quoted field', this.fieldLine, this.fieldColumn);
      default: // UNQUOTED, QUOTE_IN_QUOTED
        this.endField(this.field);
    }
    this.endRecord();
  }

  /** Returns the records completed since the last call. */
  take() {
    const records = this.records;
    this.records = [];
    return records;
  }

  // Handles the first character of a field that is not a line break; returns
  // where the field's content starts in the chunk.
  startField(c, i) {
    this.fieldLine = this.line;
    this.fieldColumn = this.column;
    if (c === QUOTE) {
      this.state = QUOTED;
      return i + 1;
    }
    if (c === this.delimiter) {
      this.endField('');
      return i;
    }
    this.state = UNQUOTED;
    return i;
  }

  endField(value) {
    if (this.headerNames !== null) {
      if (this.headerNames.has(value)) {
        throw new CsvError(
          `Duplicate header name ${JSON.stringify(value)}`,
          this.fieldLine,
          this.fieldColumn,
        );
      }
      this.headerNames.add(value);
    }
    this.fields.push(value);
    this.field = '';
    this.state = FIELD_START;
  }

  endRecord() {
    const fields = this.fields;
    this.fields = [];
    this.state = RECORD_START;
    if (!this.header) {
      this.records.push(fields);
      return;
    }
    if (this.columns === null) {
      this.columns = fields;
      this.headerNames = null;
      return;
    }
    const columns = this.columns;
    if (fields.length !== columns.length) {
      throw new CsvError(
        `Expected ${columns.length} fields but found ${fields.length}`,
        this.recordLine,
        1,
      );
    }
    // fromEntries defines own properties, so a column named "__proto__" is kept as data.
    this.records.push(Object.fromEntries(columns.map((name, k) => [name, fields[k]])));
  }
}

/**
 * Parses CSV text into an array of records: arrays of strings, or objects keyed
 * by the first record when `options.header` is true.
 *
 * @param {string} text
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>}
 * @throws {TypeError} if `text` is not a string or an option is invalid.
 * @throws {CsvError} if the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`text must be a string, received ${describe(text)}`);
  }
  const tokenizer = new Tokenizer(options);
  tokenizer.feed(text);
  tokenizer.finish();
  return tokenizer.take();
}

/**
 * Creates a streaming parser with the same options and results as `parse`.
 * `write(chunk)` returns the records whose terminating line break was in
 * `chunk`; `end()` returns the rest. Once `end()` has been called or either
 * method has thrown, both methods throw.
 *
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {{write(chunk: string): Array, end(): Array}}
 */
function createParser(options = {}) {
  const tokenizer = new Tokenizer(options);
  let closedReason = null;

  function run(method, step) {
    if (closedReason !== null) {
      throw new Error(`Cannot call ${method}(): the parser ${closedReason}`);
    }
    try {
      step();
    } catch (err) {
      closedReason = 'failed with an earlier error';
      throw err;
    }
    return tokenizer.take();
  }

  return {
    write(chunk) {
      return run('write', () => {
        if (typeof chunk !== 'string') {
          throw new TypeError(`chunk must be a string, received ${describe(chunk)}`);
        }
        tokenizer.feed(chunk);
      });
    },
    end() {
      const records = run('end', () => tokenizer.finish());
      closedReason = 'has already ended';
      return records;
    },
  };
}

function toText(value, rowIndex, fieldIndex) {
  switch (typeof value) {
    case 'string':
      return value;
    case 'number':
    case 'boolean':
      return String(value);
    case 'undefined':
      return '';
    default:
      if (value === null) return '';
      throw new TypeError(
        `Unsupported value of type ${describe(value)} in row ${rowIndex}, field ${fieldIndex}`,
      );
  }
}

function quote(text) {
  return `"${text.replace(/"/g, '""')}"`;
}

function formatField(text, delimiter) {
  if (
    /["\r\n]/.test(text) ||
    text.includes(delimiter) ||
    text.startsWith(' ') ||
    text.endsWith(' ')
  ) {
    return quote(text);
  }
  return text;
}

function formatRecord(values, delimiter, rowIndex, isFirstLine) {
  const fields = new Array(values.length);
  for (let k = 0; k < values.length; k++) {
    fields[k] = formatField(toText(values[k], rowIndex, k), delimiter);
  }
  // An empty line would parse back as [''] or be skipped, so keep the field visible.
  if (fields.length === 1 && fields[0] === '') return '""';
  const line = fields.join(delimiter);
  if (isFirstLine && line.charCodeAt(0) === BOM) {
    // parse drops a leading U+FEFF as a byte order mark. Only an unquoted first
    // field can put one there (by starting with it, or by being empty before a
    // U+FEFF delimiter), and such a field has no `"` to escape.
    fields[0] = `"${fields[0]}"`;
    return fields.join(delimiter);
  }
  return line;
}

function resolveHeader(header) {
  if (header === undefined || header === null || header === false) return null;
  if (!Array.isArray(header)) {
    throw new TypeError(`options.header must be an array of column names, received ${describe(header)}`);
  }
  for (let k = 0; k < header.length; k++) {
    if (typeof header[k] !== 'string') {
      throw new TypeError(`options.header[${k}] must be a string, received ${describe(header[k])}`);
    }
  }
  return header;
}

/**
 * Serializes records to CSV text. Each record is an array of values, or, when
 * `options.header` is an array of column names, an object whose own properties
 * are written in header order after a header row.
 *
 * @param {Array<Array<unknown> | Record<string, unknown>>} rows
 * @param {{delimiter?: string, eol?: '\r\n' | '\n', header?: string[]}} [options]
 * @returns {string} The CSV text, ending with `eol`, or '' when nothing is written.
 * @throws {TypeError} for invalid rows, values or options.
 */
function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) {
    throw new TypeError(`rows must be an array, received ${describe(rows)}`);
  }
  checkOptionsObject(options);
  const delimiter = resolveDelimiter(options.delimiter);
  const eol = options.eol === undefined ? DEFAULT_EOL : options.eol;
  if (!ALLOWED_EOLS.includes(eol)) {
    throw new TypeError(`options.eol must be '\\r\\n' or '\\n', received ${describeReceived(eol)}`);
  }
  const header = resolveHeader(options.header);

  const lines = [];
  if (header !== null) lines.push(formatRecord(header, delimiter, 'header', true));
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    let values;
    if (Array.isArray(row)) {
      values = row;
    } else if (header !== null && typeof row === 'object' && row !== null) {
      values = header.map((name) => (Object.hasOwn(row, name) ? row[name] : undefined));
    } else {
      const expected = header === null ? 'an array' : 'an array or an object';
      throw new TypeError(`Row ${r} must be ${expected}, received ${describe(row)}`);
    }
    lines.push(formatRecord(values, delimiter, r, lines.length === 0));
  }
  if (lines.length === 0) return '';
  return lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

