'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv.js');

// Runs fn and returns its records, or the position of the CsvError it threw.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    if (!(err instanceof CsvError)) throw err;
    return { error: { message: err.message, line: err.line, column: err.column } };
  }
}

function parseChunks(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.write(chunk));
  records.push(...parser.end());
  return records;
}

function splitAt(text, cuts) {
  const chunks = [];
  let start = 0;
  for (const cut of cuts) {
    chunks.push(text.slice(start, cut));
    start = cut;
  }
  chunks.push(text.slice(start));
  return chunks;
}

// Inputs chosen so that some split falls between CR and LF, inside a quoted
// field, between the quotes of "", right after a closing quote, and right after
// the BOM; several of them are malformed.
const CORPUS = [
  '',
  '\uFEFF',
  '\uFEFFa,b\r\nc,d\r\n',
  'a,b\r\n\r\nc\r',
  'a\r\r\n\n\rb',
  '"a""b",c\r\n"d\r\ne",""\r\n',
  '"x""",""""\n"",',
  ',,\n,\r\n\r\n',
  'h1,h2\r\n1,2\r\n\r\n3,4\r\n',
  'h1;h2\n"a;b";"c\rd"\n',
  '\n\nh\n\nv\n\n',
  '"a"b\nc',
  'a,"b\nc',
  'h,h\n1,2',
  'h1,h2\n1,2,3\n"open',
  'h1,h2\n1,"2"x',
  '\u{1F600},"\u00e9\r\n"x',
];

const OPTION_SETS = [
  {},
  { skipEmptyLines: true },
  { header: true },
  { header: true, skipEmptyLines: true },
  { delimiter: ';' },
];

describe('createParser: matches parse wherever the input is split', () => {
  for (const options of OPTION_SETS) {
    it(`every one- and two-cut split with ${JSON.stringify(options)}`, () => {
      for (const text of CORPUS) {
        const expected = outcome(() => parse(text, options));
        for (let a = 0; a <= text.length; a++) {
          const one = outcome(() => parseChunks(splitAt(text, [a]), options));
          assert.deepEqual(one, expected, `${JSON.stringify(text)} cut at ${a}`);
          for (let b = a; b <= text.length; b++) {
            const two = outcome(() => parseChunks(splitAt(text, [a, b]), options));
            assert.deepEqual(two, expected, `${JSON.stringify(text)} cut at ${a},${b}`);
          }
        }
      }
    });

    it(`one character per write with ${JSON.stringify(options)}`, () => {
      for (const text of CORPUS) {
        const expected = outcome(() => parse(text, options));
        assert.deepEqual(outcome(() => parseChunks([...text.split(''), ''], options)), expected, JSON.stringify(text));
      }
    });
  }
});

describe('createParser: when records are returned', () => {
  it('returns a record from the write whose chunk holds its line break', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b\nc'), [['a', 'b']]);
    assert.deepEqual(parser.write(',d\r'), [['c', 'd']]);
    assert.deepEqual(parser.write('\ne'), []);
    assert.deepEqual(parser.write(''), []);
    assert.deepEqual(parser.end(), [['e']]);
  });

  it('returns an empty line from the write that ends it', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\r'), [['']]);
    assert.deepEqual(parser.write('\n'), []);
    assert.deepEqual(parser.end(), []);
  });

  it('holds a record whose quoted field is still open', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('"a\n'), []);
    assert.deepEqual(parser.write('b"'), []);
    assert.deepEqual(parser.write('"'), []);
    assert.deepEqual(parser.write('"\n'), [['a\nb"']]);
    assert.deepEqual(parser.end(), []);
  });

  it('never returns the header record in header mode', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('a,b\n'), []);
    assert.deepEqual(parser.write('1,2\n3,'), [{ a: '1', b: '2' }]);
    assert.deepEqual(parser.end(), [{ a: '3', b: '' }]);
  });

  it('returns each record once', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\nb\n'), [['a'], ['b']]);
    assert.deepEqual(parser.write('c\n'), [['c']]);
    assert.deepEqual(parser.end(), []);
  });
});

describe('createParser: argument and lifecycle errors', () => {
  it('validates options when the parser is created', () => {
    assert.throws(() => createParser({ delimiter: '"' }), TypeError);
    assert.throws(() => createParser({ header: 1 }), TypeError);
    assert.throws(() => createParser(null), TypeError);
  });

  for (const [label, chunk] of [
    ['undefined', undefined],
    ['null', null],
    ['a number', 1],
    ['a Buffer', Buffer.from('a')],
  ]) {
    it(`throws TypeError when a chunk is ${label}, then refuses further calls`, () => {
      const parser = createParser();
      assert.throws(() => parser.write(chunk), TypeError);
      assert.throws(() => parser.write('a'), { name: 'Error', message: /failed/ });
      assert.throws(() => parser.end(), { name: 'Error', message: /failed/ });
    });
  }

  it('throws Error from both methods after end()', () => {
    const parser = createParser();
    parser.write('a');
    assert.deepEqual(parser.end(), [['a']]);
    assert.throws(() => parser.write('b'), { name: 'Error', message: /ended/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /ended/ });
  });

  it('throws Error from both methods after write() throws a CsvError', () => {
    const parser = createParser();
    assert.throws(() => parser.write('"a"b'), CsvError);
    assert.throws(() => parser.write('\n'), { name: 'Error' });
    assert.throws(() => parser.end(), { name: 'Error' });
  });

  it('throws Error from both methods after end() throws a CsvError', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('"open'), []);
    assert.throws(() => parser.end(), { name: 'CsvError', line: 1, column: 1 });
    assert.throws(() => parser.write('"'), { name: 'Error', message: /failed/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /failed/ });
  });

  it('keeps separate parsers independent', () => {
    const first = createParser({ header: true });
    const second = createParser({ delimiter: ';' });
    assert.deepEqual(first.write('a,b\n'), []);
    assert.deepEqual(second.write('x;y\n'), [['x', 'y']]);
    assert.deepEqual(first.write('1,2\n'), [{ a: '1', b: '2' }]);
    assert.deepEqual(first.end(), []);
    assert.deepEqual(second.end(), []);
  });
});

describe('createParser: stress', () => {
  it('handles 300k one-character writes in linear time', { timeout: 10_000 }, () => {
    const field = 'x"'.repeat(50_000); // 100k characters, 50k escaped quotes
    const text = `"${field.replace(/"/g, '""')}",b\r\n${'1,2\r\n'.repeat(40_000)}`;
    const parser = createParser();
    let records = 0;
    let first;
    for (let i = 0; i < text.length; i++) {
      const out = parser.write(text[i]);
      if (out.length > 0 && first === undefined) first = out[0];
      records += out.length;
    }
    records += parser.end().length;
    assert.ok(text.length > 300_000);
    assert.deepEqual(first, [field, 'b']);
    assert.equal(records, 40_001);
  });
});

