  const comment = { comment: '#' };

  it('is off by default', () => {
    assert.deepEqual(parse('#a\nb'), [['#a'], ['b']]);
    assert.deepEqual(parse('#a\nb', { comment: undefined }), [['#a'], ['b']]);
  });

  it('skips a whole line with its line break', () => {
    assert.deepEqual(parse('#one\na,b\n#two\r\n#three\rc\r\n', comment), [['a', 'b'], ['c']]);
