  const trim = { trim: true };

  it('is off by default and changes nothing then', () => {
    assert.deepEqual(parse(' a , b \t'), [[' a ', ' b \t']]);
    assert.deepEqual(parse(' a ', { trim: false }), [[' a ']]);
    assert.deepEqual(parse(' a ', { trim: undefined }), [[' a ']]);
    assert.deepEqual(parse(' "a"'), [[' "a"']]);
    assertCsvError(() => parse('"a" ,b'), 1, 4);
  });

  it('removes spaces and tabs from both ends of unquoted fields', () => {
    assert.deepEqual(parse(' a , \tb c\t ,d\r\n\t\te\t', trim), [['a', 'b c', 'd'], ['e']]);
  });

  it('only removes spaces and tabs', () => {
    assert.deepEqual(parse(' a ,   ', trim), [[' a ', ' ']]);
    assert.deepEqual(parse('\fa\v', trim), [['\fa\v']]);
  });

  it('turns a field of only spaces and tabs into an empty field', () => {
    assert.deepEqual(parse(' , \t ,  ', trim), [['', '', '']]);
    assert.deepEqual(parse('a,  \nb,\t', trim), [['a', ''], ['b', '']]);
  });

  it('keeps a line of only spaces as the record [""], even with skipEmptyLines', () => {
    assert.deepEqual(parse('a\n  \n\nb\n', trim), [['a'], [''], [''], ['b']]);
    assert.deepEqual(parse('a\n \t\n\nb\n', { trim: true, skipEmptyLines: true }), [['a'], [''], ['b']]);
    assert.deepEqual(parse('  ', trim), [['']]);
  });

  it('allows spaces and tabs around quoted fields and keeps the quoted content exactly', () => {
    assert.deepEqual(parse(' \t"  a ""b"" \t" \t,\t"c"\t\r\n "d\n"  ', trim), [
      ['  a "b" \t', 'c'],
      ['d\n'],
    ]);
    assert.deepEqual(parse('  "" ,  "  "  ', trim), [['', '  ']]);
  });

  it('treats a field with spaces before the opening quote as quoted', () => {
    assert.deepEqual(parse('  "a,b"  ,c', trim), [['a,b', 'c']]);
    assert.deepEqual(parse('  "a\r\nb"', trim), [['a\r\nb']]);
    assertCsvError(() => parse('  "open', trim), 1, 3, /Unclosed/);
  });

