    assert.deepEqual(parse(' a "b" ,  x"', trim), [['a "b"', 'x"']]);
  });

  it('still rejects other characters after a closing quote', () => {
    assertCsvError(() => parse('"a" b', trim), 1, 5, /after closing quote/);
    assertCsvError(() => parse('x,  "a" \t"', trim), 1, 10);
    assertCsvError(() => parse('"a" ', trim), 1, 4);
  });

  it('trims before checking duplicate header names', () => {
    assert.deepEqual(parse(' a , b \n 1 , "2 " \n', { trim: true, header: true }), [{ a: '1', b: '2 ' }]);
    assertCsvError(() => parse('a, "a"', { trim: true, header: true }), 1, 4, /Duplicate/);
  });

  it('never trims a delimiter that is a space or tab', () => {
    assert.deepEqual(parse(' a \t b  c ', { trim: true, delimiter: ' ' }), [['', 'a', '\t', 'b', '', 'c']]);
    assert.deepEqual(parse(' a \t b\t\tc ', { trim: true, delimiter: '\t' }), [['a', 'b', '', 'c']]);
    assert.deepEqual(parse('"a"\t "b" \t', { trim: true, delimiter: '\t' }), [['a', 'b', '']]);
  });

