    assert.deepEqual(parse('a\n#x', comment), [['a']]);
    assert.deepEqual(parse('a\n#x\n', comment), [['a']]);
    assert.deepEqual(parse('a\r\n#x\r\n', comment), [['a']]);
    assert.deepEqual(parse('#x', comment), []);
    assert.deepEqual(parse('#', comment), []);
  });

  it('is not an empty line and never becomes a record', () => {
    assert.deepEqual(parse('#x\n', comment), []);
    assert.deepEqual(parse('a\n#x\n\nb', comment), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n#x\n\nb', { comment: '#', skipEmptyLines: true }), [['a'], ['b']]);
  });

  it('is ordinary anywhere but the first character of a line', () => {
    assert.deepEqual(parse('a#,#b#\n b,#\n"#",\n"x\n#y"', comment), [
      ['a#', '#b#'],
      [' b', '#'],
      ['#', ''],
      ['x\n#y'],
    ]);
    assert.deepEqual(parse(' #a\n\t#b', { comment: '#', trim: true }), [['#a'], ['#b']]);
  });

  it('applies after a byte order mark', () => {
    assert.deepEqual(parse('﻿#a\nb', comment), [['b']]);
  });

  it('skips comment lines before the header and between records', () => {
    assert.deepEqual(parse('#c\nh1,h2\n#c\n1,2\n#c\n3,4', { comment: '#', header: true }), [
      { h1: '1', h2: '2' },
      { h1: '3', h2: '4' },
    ]);
  });

  it('counts comment lines in error line numbers', () => {
    assertCsvError(() => parse('#a\n#b\n"x"y', comment), 3, 4);
    assertCsvError(() => parse('a\r\n#b\r\n#c\r"open', comment), 4, 1, /Unclosed/);
    assertCsvError(() => parse('#c\nh1,h2\n#c\n1,2,3', { comment: '#', header: true }), 4, 1);
    assertCsvError(() => parse('#c\r#c\nh,h', { comment: '#', header: true }), 3, 3, /Duplicate/);
  });

  it('works with any other character, including one that is a space or tab', () => {
    assert.deepEqual(parse(';x\na;\n', { comment: ';' }), [['a;']]);
    assert.deepEqual(parse(' x\n a\n', { comment: ' ' }), []);
    assert.deepEqual(parse('\tx\na', { comment: '\t', trim: true }), [['a']]);
    assert.deepEqual(parse('#x\na;b', { comment: '#', delimiter: ';' }), [['a', 'b']]);
  });

  for (const [label, value] of [
    ['empty', ''],
    ['two characters', '//'],
    ['the default delimiter', ','],
    ['a quote', '"'],
    ['CR', '\r'],
    ['LF', '\n'],
    ['null', null],
    ['a number', 35],
    ['an array', ['#']],
    ['a String object', new String('#')],
    ['an astral character', '\u{1F600}'],
  ]) {
    it(`throws TypeError when comment is ${label}`, () => {
      assert.throws(() => parse('a', { comment: value }), TypeError);
    });
  }

  it('throws TypeError when comment equals a custom delimiter', () => {
    assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
    assert.deepEqual(parse('#a,b', { comment: ',', delimiter: ';' }), [['#a,b']].slice(1));
  });
});
